23: static void mandel_row(float x0, float y0, float dx, float dy, int width, int j, int maxIterations, int output[]) {
24:     for (int i = 0; i < width; ++i) {
25:         float x = x0 + i * dx;
26:         float y = y0 + j * dy;
27: 
28:         int index = (j * width + i);
29:         output[index] = mandel(x, y, maxIterations);
30:     }
31: }
