static int mandel(float c_re, float c_im, int count) {
    float z_re = c_re, z_im = c_im;
    int i;
    for (i = 0; i < count; ++i) {
        if (z_re * z_re + z_im * z_im > 4.f)
            break;

        float new_re = z_re * z_re - z_im * z_im;
        float new_im = 2.f * z_re * z_im;
        z_re = c_re + new_re;
        z_im = c_im + new_im;
    }

    return i;
}

static void mandel_row(float x0, float y0, float dx, float dy, int width, int j, int maxIterations, int output[]) {
    for (int i = 0; i < width; ++i) {
        float x = x0 + i * dx;
        float y = y0 + j * dy;

        int index = (j * width + i);
        output[index] = mandel(x, y, maxIterations);
    }
}

static void mandelbrot_serial(float x0, float y0, float x1, float y1, int width, int height, int maxIterations, int output[], int threads) {
    float dx = (x1 - x0) / width;
    float dy = (y1 - y0) / height;

    if (threads <= 1) {
        for (int j = 0; j < height; ++j)
            mandel_row(x0, y0, dx, dy, width, j, maxIterations, output);
    } else {
        #pragma omp parallel for schedule(dynamic, 1) num_threads(threads)
        for (int j = 0; j < height; ++j)
            mandel_row(x0, y0, dx, dy, width, j, maxIterations, output);
    }
}

