26: static inline void mandel_row(float x0, float y, float dx, int j,
27:                               int width, int maxIterations, int output[]) {
28:     int i = 0;
29:     const __m128 four = _mm_set1_ps(4.f);
30:     const __m128 two = _mm_set1_ps(2.f);
31:     const __m128 y_value = _mm_set1_ps(y);
32:     const __m128 all_lanes = _mm_castsi128_ps(_mm_set1_epi32(-1));
33:     const __m128i one = _mm_set1_epi32(1);
34: 
35:     for (; i + 4 <= width; i += 4) {
36:         const __m128 c_re = _mm_set_ps(
37:             x0 + (i + 3) * dx,
38:             x0 + (i + 2) * dx,
39:             x0 + (i + 1) * dx,
40:             x0 + i * dx);
41:         __m128 z_re = c_re;
42:         __m128 z_im = y_value;
43:         __m128 active = all_lanes;
44:         __m128i pixel_counts = _mm_setzero_si128();
45: 
46:         // The initial mask is nonzero, and each continuing iteration leaves it nonzero.
47:         for (int iter = 0; iter < maxIterations; ++iter) {
48:             const __m128 magnitude = _mm_add_ps(
49:                 _mm_mul_ps(z_re, z_re), _mm_mul_ps(z_im, z_im));
50:             const __m128 escaped = _mm_cmpgt_ps(magnitude, four);
51:             active = _mm_andnot_ps(escaped, active);
52:             if (_mm_movemask_ps(active) == 0)
53:                 break;
54: 
55:             pixel_counts = _mm_add_epi32(
56:                 pixel_counts,
57:                 _mm_and_si128(_mm_castps_si128(active), one));
58: 
59:             // Escaped lanes no longer contribute to counts; their state is irrelevant.
60:             const __m128 new_re = _mm_sub_ps(
61:                 _mm_mul_ps(z_re, z_re), _mm_mul_ps(z_im, z_im));
62:             const __m128 two_times_re = _mm_mul_ps(two, z_re);
63:             const __m128 new_im = _mm_mul_ps(two_times_re, z_im);
64:             z_re = _mm_add_ps(c_re, new_re);
65:             z_im = _mm_add_ps(y_value, new_im);
66:         }
67: 
68:         _mm_storeu_si128(
69:             reinterpret_cast<__m128i *>(output + j * width + i), pixel_counts);
70:     }
71: 
72:     for (; i < width; ++i) {
73:         float x = x0 + i * dx;
74:         output[j * width + i] = mandel(x, y, maxIterations);
75:     }
76: }
