78: static void mandelbrot_simd(float x0, float y0, float x1, float y1,
79:                             int width, int height, int maxIterations, int output[],
80:                             int threads) {
81:     float dx = (x1 - x0) / width;
82:     float dy = (y1 - y0) / height;
83: 
84:     if (threads <= 1) {
85:         for (int j = 0; j < height; ++j) {
86:             float y = y0 + j * dy;
87:             mandel_row(x0, y, dx, j, width, maxIterations, output);
88:         }
89:     } else {
90:         #pragma omp parallel for schedule(dynamic, 1) num_threads(threads)
91:         for (int j = 0; j < height; ++j) {
92:             float y = y0 + j * dy;
93:             mandel_row(x0, y, dx, j, width, maxIterations, output);
94:         }
95:     }
96: }
