32:     const __m128 all_lanes = _mm_castsi128_ps(_mm_set1_epi32(-1));
33:     const __m128i one = _mm_set1_epi32(1);
34: 
35:     for (; i + 4 <= width; i += 4) {
36:         const __m128 c_re = _mm_set_ps(
37:             x0 + (i + 3) * dx,
38:             x0 + (i + 2) * dx,
39:             x0 + (i + 1) * dx,
40:             x0 + i * dx);
41:         __m128 z_re = c_re;
42:         __m128 z_im = y_value;
43:         __m128 active = all_lanes;
44:         __m128i pixel_counts = _mm_setzero_si128();
45: 
46:         for (int iter = 0; iter < maxIterations; ++iter) {
47:             const __m128 magnitude = _mm_add_ps(
