10: static int mandel(float c_re, float c_im, int count) {
11:     float z_re = c_re, z_im = c_im;
12:     int i;
13:     for (i = 0; i < count; ++i) {
14:         if (z_re * z_re + z_im * z_im > 4.f)
15:             break;
16: 
17:         float new_re = z_re * z_re - z_im * z_im;
18:         float new_im = 2.f * z_re * z_im;
19:         z_re = c_re + new_re;
20:         z_im = c_im + new_im;
21:     }
22: 
23:     return i;
24: }
